/*
 * A117296  Numbers n for which phi(n) is a palindrome.
 * https://oeis.org/A117296
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   a(n) = the n-th integer m (n ≥ 1) such that φ(m) is a palindrome
 *            in base 10. The sequence is generated by scanning successive
 *            integers and collecting those whose Euler's totient value reads
 *            the same forwards and backwards
 * Range:     u8 n <= 32, u16 n <= 762, u32 n <= 2000, u64 n <= 2000,
 *            u128 n <= 2000, big any n
 * Helpers:   is_palindrome, phi
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>          /* bool, false, true */
#include <stddef.h>           /* size_t */

#include "../utils/phi.h"         /* seq_t phi(idx_t m); */
#include "../utils/is_palindrome.h" /* bool is_palindrome(seq_t x, idx_t base); */

/* Maximum number of terms we are prepared to keep.  The tests only request
   up to about 10 000 terms, so 20 000 provides a generous safety margin. */
#define MAX_TERMS 20000

static seq_t terms[MAX_TERMS];   /* stored sequence values */
static size_t terms_size = 0;    /* current number of stored terms */
static idx_t last_checked = 0;   /* last m that has been examined */

/* Append a new term to the static array.  The caller guarantees not to
   exceed MAX_TERMS. */
static void append_term(idx_t val) {
    if (terms_size < MAX_TERMS) {
        terms[terms_size++] = (seq_t)val;   /* implicit conversion */
    }
}

/* Main sequence function: a(idx_t n) */
seq_t a(idx_t n) {
    if (n == 0) return 0;                 /* undefined offset; safe default */

    /* Return cached result if already computed */
    if ((size_t)(n - 1) < terms_size) {
        return terms[n - 1];
    }

    /* Generate new terms until we have at least n of them */
    while (terms_size < (size_t)n) {
        /* examine next integer */
        ++last_checked;

        seq_t phi_val = phi(last_checked);
        if (is_palindrome(phi_val, (idx_t)10)) {
            append_term(last_checked);
        }
    }

    return terms[n - 1];
}
